  'landing.basicPt1': 'Modelos 2D y 3D simples: vigas, pórticos, reticulados, arcos y pórticos espaciales.',
  'landing.basicPt2': 'El razonamiento de un curso inicial e intermedio de estructuras: estabilidad, reacciones, esfuerzos internos, deformaciones y tensiones de sección.',
