  'landing.basicDemoNote': 'La demo en vivo de acá abajo corre el modo Básico tal como se publica. Educativo y PRO construyen más flujos sobre la misma base de cálculo estructural.',
  'landing.demoBasicPill': '100% modo Básico',
  'landing.demoScopeNote': 'Todo lo que ves en esta ventana es el modo Básico que obtenés en stabileo.com, corriendo en tu navegador. Educativo y PRO extienden la misma base con sus propios flujos.',
  'landing.ebEdu': 'MODO EDUCATIVO',
  'landing.eduH': 'El modo Educativo se construye sobre Básico.',
  'landing.eduP': 'Una capa de ejercicios para estudiantes construida sobre el mismo motor de cálculo. El docente escribe el ejercicio dentro de la app, lo reparte como link y recibe las respuestas; lo que falta es la capa de arriba: la cátedra.',
  'landing.eduNowKicker': 'YA FUNCIONA',
  'landing.eduNowTitleNew': 'La capa de ejercicios del estudiante',
  'landing.eduNow1': 'Siete ejercicios predefinidos, agrupados en estática, resistencia y avanzados.',
  'landing.eduNow2': 'El modelo se carga y se resuelve solo. Las respuestas correctas salen del solver, no de una clave guardada.',
  'landing.eduNow3': 'Preguntas sobre reacciones, sobre valores y formas de los diagramas, sobre cinemática (isostático o hiperestático, y el grado) y sobre datos de la sección.',
  'landing.eduNow4': 'El alumno DIBUJA el diagrama —las ordenadas y la potencia de cada tramo— y el trazo y las potencias se corrigen por separado contra el cálculo. Corte, momento, axil y la deformada.',
  'landing.eduNow5': 'Las respuestas se verifican con una tolerancia, con una pista cuando lo que falló es el signo o el orden de magnitud. Los resultados quedan ocultos mientras trabajás; si se pueden revelar o no lo decide el docente.',
  'landing.eduNow6': 'El docente escribe el ejercicio en la app: dibuja la estructura con las herramientas de siempre y después dice qué preguntar sobre ella. Sin código y sin archivos que editar.',
  'landing.eduNow7': 'Repartirlo es un link o un archivo, y abre un entorno hecho para el alumno. Él devuelve un archivo o un código corto, y el docente lo abre como una tabla corregida.',
  'landing.eduNextKicker': 'EN DESARROLLO',
  'landing.eduNextTitle': 'Flujos docentes en desarrollo',
  'landing.eduNext1': 'Tareas que agrupen varios ejercicios, con fecha de entrega y un curso al que repartirlas.',
  'landing.eduNext2': 'Más del ejercicio bajo control del docente: qué pistas aparecen, cuándo se ven los resultados, cuántos intentos.',
  'landing.eduNext3': 'Flujos para que el estudiante inspeccione, repare y construya modelos, y no sólo lea uno.',
  'landing.eduNext4': 'Una progresión con forma de materia: estabilidad, reacciones, desplazamientos, diagramas, cinemática, análisis de secciones.',
  'landing.eduNext5': 'Ayuda con la terminología, donde el alumno se cruza una palabra por primera vez.',
  'landing.eduNext6': 'Onboarding separado para docentes y para estudiantes.',
  'landing.eduNotYet': 'Lo que existe es el ejercicio y la vuelta completa alrededor de él: el docente lo escribe, lo reparte y lee las respuestas. Lo que no existe es la cátedra alrededor de ESO — tareas, lista de curso, intentos, una nota que viva en algún lado. Stabileo no guarda nada en un servidor, así que un ejercicio y una entrega viajan como link, archivo o código, tal como ya se entrega. Las lecciones paso a paso del método de rigidez están disponibles como parte de Básico.',
  'landing.eduFree': 'La intención es que el núcleo educativo siga siendo gratuito para uso educativo.',
  'landing.ebPro': 'MODO PRO',
  'landing.proH': 'PRO está en desarrollo, y ya sirve para cálculos complejos.',
  'landing.proP': 'El análisis con elementos finitos y los modelos complejos ya funcionan acá, al nivel que esperarías de un programa profesional. Lo que se está puliendo es el diseño según normativa: el paso en el que muchos programas de elementos finitos se detienen, te entregan los resultados y te dejan la verificación reglamentaria a vos.',
