  'config.tip.localAxesShells': 'Lo mismo para placas y cuadriláteros: las direcciones en las que se informan sus resultados de flexión y membrana.',
  'config.tip.showGrid': 'La grilla de referencia detrás del modelo. Apagarla no cambia cómo se ajusta lo que dibujás.',
  'config.tip.snapGrid': 'Los nodos nuevos caen en la intersección de grilla más cercana en vez de exactamente donde clickeaste.',
  'config.tip.gridSize': 'Distancia entre líneas de la grilla, y por lo tanto el paso al que se ajusta un nodo.',
  'config.tip.gridExtent': 'Hasta dónde llega la grilla desde el origen. Es sólo lo que ves: no limita dónde podés dibujar.',
  'config.tip.smoothOrbit': 'La cámara conserva algo de inercia al soltar el mouse, en vez de frenar en seco.',
  'config.tip.nodeIds': 'Escribe el número de cada nodo al lado — los mismos números que usa la tabla de resultados.',
  'config.tip.elementIds': 'Escribe el número de cada barra sobre ella, así un resultado de la tabla se ubica en el modelo.',
  'config.tip.lengths': 'Rotula cada barra con su longitud. Una forma rápida de detectar un nodo puesto un metro más allá.',
  'config.tip.showLoads': 'Dibuja las cargas sobre el modelo. Apagarlas deja la estructura desnuda, más fácil de leer mientras editás geometría.',
  'config.tip.units': 'El sistema de unidades en el que se expresan todos los campos y resultados. Cambiarlo convierte lo que ya está cargado.',
  'config.tip.axisConvention': 'Qué regla de la mano siguen los ejes locales. Define el signo de los momentos y el lado hacia el que se dibuja un diagrama, no la magnitud de nada.',
  'config.tip.momentStyle': 'Cómo se dibuja un momento: una flecha de doble punta sobre el eje en torno al que gira, o una flecha curva que muestra el giro.',
  'config.tip.renderMode': 'Barras como líneas, como barras sólidas, o con su sección real extruida a lo largo. Las líneas son lo más rápido en un modelo grande.',
  'config.tip.color': 'Colorea las barras todas iguales, o según el material o la sección asignada a cada una: un chequeo rápido de que fue la correcta a donde querías.',
  'config.tip.autoSplit': 'Poner un nodo sobre una barra existente la parte en dos en ese punto, en vez de dejar un nodo apoyado sobre una barra entera.',
  'config.tip.showValues': 'Escribe los números sobre el diagrama: los picos y los extremos, en vez de sólo la forma.',
  'config.tip.showReactions': 'Dibuja las fuerzas que los apoyos le devuelven a la estructura. Su suma tiene que equilibrar la carga aplicada, así que son lo primero para chequear.',
  'config.tip.showConstraintForces': 'Dibuja las fuerzas que toman los desplazamientos impuestos y los vínculos rígidos: las que no son reacciones en un apoyo.',
  'config.tip.hideLoadsWithDiagram': 'Esconde las flechas de carga mientras hay un diagrama en pantalla, para que no se superpongan sobre las mismas barras.',
  'config.tip.showPrimarySelector': 'El selector que elige QUÉ resultado se muestra: cargas simples, un estado de carga, una combinación o la envolvente.',
  'config.tip.showSecondarySelector': 'El selector «Comparar», que superpone un segundo resultado sobre el primero para leerlos uno contra otro. Necesita el selector principal encendido.',
  'config.tip.drawPositiveTowardLocalAxes': 'De qué lado se dibuja un valor positivo: hacia los ejes locales de la barra, o del lado estructural — la flexión positiva hacia abajo, como se dibuja a mano.',
