  'slab.maturity.promotionPath': 'Contrastar contra un ejemplo resuelto de losa en dos direcciones del reglamento o de bibliografía reconocida, con momentos de Wood-Armer y armadura resultante.',
  'slab.maturity.leverArm': 'Brazo elástico interno adoptado como 0,9 d, habitual en losas de armadura reducida.',
  'wall.maturity.promotionPath': 'Contrastar la interacción carga axial-flexión contra un diagrama de interacción completo o un ejemplo resuelto de tabique.',
  'wall.maturity.simplifiedInteraction': 'La resistencia a flexión usa la expresión simplificada de armadura distribuida en sección rectangular, que aproxima la superficie de interacción real.',
  'detailing.slabPunching.staleAnalysis': 'Losa {panel}, nudo {node} (columna {column}): el punzonado NO está verificado porque la solicitación del panel proviene de un análisis anterior al modelo. El salto de la fuerza axial de la columna se leería de resultados que ya no describen esta estructura, y una verificación de punzonado construida sobre fuerzas vencidas es la verificación de un edificio que no existe. Recalcular y volver a diseñar.',
  'detailing.slabPunching.oppositeRuns': 'Losa {panel}, nudo {node} (columna {column}): la losa llega al nudo con {coverage}° repartidos en dos tramos OPUESTOS, una condición de franja. El artículo 22.6.5.3 tabula α_s sólo para columna interior, de borde y de esquina, y un perímetro truncado en dos caras opuestas no es ninguno de los tres. El punzonado se informa como NO verificado en lugar de aproximarse con un α_s equivocado.',
  'detailing.slabPunching.reEntrant': 'Losa {panel}, nudo {node} (columna {column}): la losa llega al nudo con {coverage}°, un rincón entrante. El perímetro crítico es una sexta forma que el artículo 22.6.5.3 no tabula, de modo que el punzonado se informa como NO verificado en lugar de adoptar un α_s que corresponde a otra geometría.',
  'detailing.slabPunching.noSlab': 'El nudo {node} (columna {column}) no tiene losa en el panel {panel}, de modo que no hay superficie de punzonado que verificar. Ángulo medido: {coverage}°.',
  'detailing.slabPunching.disjointRuns': 'Losa {panel}, nudo {node} (columna {column}): la losa llega al nudo con {coverage}° repartidos en tramos separados. El perímetro crítico no es ninguna de las tres formas que tabula el artículo 22.6.5.3, de modo que el punzonado se informa como NO verificado.',
  'detailing.slabPunching.skewed': 'Losa {panel}, nudo {node} (columna {column}): la losa llega al nudo con {coverage}°, que dentro de la tolerancia no es 90°, 180°, 270° ni 360°. La posición no puede clasificarse como interior, de borde o de esquina, de modo que el punzonado se informa como NO verificado en lugar de redondearse al caso tabulado más próximo.',
  'detailing.slabPunching.missingGeometry': 'Losa {panel}, nudo {node} (columna {column}): el punzonado necesita una altura útil positiva, las dimensiones en planta de la columna y una resistencia del hormigón. Medidos: espesor {thickness} m, recubrimiento {cover} m, columna {b} × {h} m, f\'c {fc} MPa. La verificación se informa como NO verificada en lugar de ejecutarse con una dimensión faltante.',
  'detailing.slabPunching.noColumnForces': 'Losa {panel}, nudo {node} (columna {column}): ninguna combinación resuelta lleva fuerza axial de columna en este nudo, de modo que la fuerza transferida no puede plantearse por equilibrio. El punzonado NO está verificado; no se adopta ningún valor supuesto.',
  'detailing.slabPunching.averageMatDepth': 'Losa {panel}, nudo {node}: la altura útil para punzonado se toma como {d} m, del espesor de la losa menos el recubrimiento y el diámetro medio de la malla superior de {diameter} mm. Las dos direcciones de la malla están realmente a alturas distintas y el perímetro crítico es una sola superficie, de modo que este promedio es una hipótesis.',
  'detailing.slabPunching.noColumnAbove': 'Losa {panel}, nudo {node} (columna {column}): no hay columna por encima del nudo, de modo que el cuerpo libre queda abierto en esa cara y toda la fuerza axial de la columna inferior pasa a ser el salto transferido. Es la condición de borde real de un nudo de azotea, no una fuerza faltante.',
  'detailing.slabPunching.noColumnBelow': 'Losa {panel}, nudo {node} (columna {column}): no hay columna por debajo del nudo, de modo que el cuerpo libre queda abierto en esa cara y toda la fuerza axial de la columna superior pasa a ser el salto transferido. Es la condición de borde real donde una columna cuelga de la losa, no una fuerza faltante.',
  'detailing.slabPunching.residualNotEstablished': 'Losa {panel}, nudo {node} (columna {column}): el cuerpo libre de punzonado no cierra en ninguna combinación resuelta. Peor caso {combination}: salto axial de {step} kN contra {deducted} kN de carga entregada directamente y apoyada dentro del perímetro crítico, con un residuo de {residual} kN. Vu resultaría un número negativo truncado en cero, es decir una verificación aprobada por aritmética y no por capacidad. El punzonado se informa como NO verificado.',
  'detailing.slabPunching.someCombinationsUnbalanced': 'Losa {panel}, nudo {node}: {count} de {total} combinaciones ({combinations}) no pudieron cerrar el cuerpo libre de punzonado y quedaron excluidas de la elección de la combinación gobernante. Las restantes sí cerraron y la verificación informada proviene de ellas.',
  'detailing.slabPunching.upliftNotEstablished': 'Losa {panel}, nudo {node} (columna {column}): el punzonado NO está verificado para la combinación {combination}: el salto axil corre en sentido INVERSO — la columna de arriba tira del nudo hacia arriba con {step} kN más que lo que la columna de abajo lo empuja hacia abajo. Es punzonado por succión, un mecanismo distinto con la cara de tracción invertida, y la verificación descendente de este registro no dice nada sobre él. La aritmética con |salto| habría ocultado la dirección por completo.',
  'detailing.slabPunching.someCombinationsUplift': 'Losa {panel}, nudo {node}: {count} de {total} combinaciones ({combinations}) llevan el nudo a SUCCIÓN — salto axil invertido — y quedaron excluidas de la elección de la gobernante. Las restantes se verifican en sentido descendente; la dirección de succión es un mecanismo distinto y NO está verificada.',
  'detailing.slabPunching.momentTransfer': 'Losa {panel}, nudo {node} (columna {column}): la combinación {combination} transfiere un momento no balanceado de {moment} kN·m con un corte en dos direcciones de {shear} kN. La transferencia de momento por corte excéntrico (artículo 8.4.4.2) no está implementada, y verificar sólo el corte directo daría por aprobado un nudo que puede no serlo. El punzonado se informa como NO verificado en este nudo.',
  'detailing.floorRun.wallUnsupported': 'Tabique {wall}: {reason}',
  'detailing.floorRun.wallBoundaryNotImplemented': 'Tabique {wall}: el proyecto tiene un reglamento sismico vinculado, por lo que puede requerirse un elemento de borde. El diseño de elementos de borde corresponde al INPRES-CIRSOC 103 Parte II y no está implementado; un elemento de borde no sismico parecería un diseño completo y no lo sería.',
  'detailing.floorRun.wallBoundaryRequired': 'Tabique {wall}: puede requerirse un elemento de borde y su diseño no está implementado.',
  'detailing.floorRun.wallBoundaryNotTriggered': 'Tabique {wall}: no hay reglamento sismico vinculado, por lo que no aplica ningún disparador de elemento de borde.',
  'footing.record.bearingUnsupported': 'No pudo completarse la verificación de capacidad portante de esta zapata; el motivo figura en las condiciones de la zapata.',
  'footing.record.punchingUnsupported': 'No pudo completarse la verificación de punzonado de esta zapata; el motivo figura en las condiciones de la zapata.',
  'footing.record.flexureNoSteel': 'La demanda de flexión (§13.2.7) está calculada y se muestra, pero no existe parrilla inferior modelada contra la cual verificarla. La flexión NO está verificada — un OK aquí sería una afirmación de capacidad que nadie calculó.',
