  'footing.migration.droppedNoNode': 'Se descartó la zapata {id}: no referenciaba ningún nudo, por lo que no tenía reacción ni posición.',
  'footing.migration.matDiameterUnsupported': 'El diámetro de parrilla inferior guardado para la dirección {axis} era Ø{value}, que no está en el catálogo de barras del proyecto. Se leyó como Ø{fallback} en lugar de aceptarse: una parrilla que nadie puede comprar no es un dimensionamiento.',
  'footing.migration.matPolicyUnknown': 'La política de separación de parrilla inferior guardada «{value}» no es una que esta versión conozca. La separación se derivó del reglamento, que es la única política implementada.',
  'footing.migration.layerOrderToAuto': 'El proyecto no indicaba qué parrilla inferior va en la capa de abajo, de modo que el orden de capas se leyó como AUTOMÁTICO. Esto CAMBIA el dimensionamiento respecto de la versión anterior: antes ambas direcciones se dimensionaban con la altura útil menor (envolvente conservadora) y ahora cada una se dimensiona con su altura real. Se puede fijar el orden a mano en Fundaciones.',
  'footing.migration.layerOrderUnknown': 'El orden de capas de la parrilla inferior guardado «{value}» no es uno que esta versión conozca. Se leyó como AUTOMÁTICO: un orden que no se puede materializar no es una instrucción de colocación.',

