  // ─── Fundaciones: la corrida de diseño ─────────────────────────
  'footing.run.kindNotImplemented': 'La zapata {footing} está modelada como {kind}, que no está implementado. No se verificó como zapata aislada, porque eso daría un resultado incorrecto con apariencia de correcto.',
  'footing.run.nodeMissing': 'Zapata {footing}: el nudo {node} no está en el modelo.',
  'footing.run.noSoilProfile': 'La zapata {footing} no apoya sobre ningún perfil de suelo, por lo que no hay tensión admisible contra la cual verificarla.',
  'footing.run.bearingUnstated': 'Zapata {footing}: el perfil {profile} no declara tensión admisible. Surge de un estudio de suelos, no de un reglamento, por lo que no puede suponerse nada.',
  'footing.run.noReaction': 'Zapata {footing}: el nudo {node} no tiene reacción, por lo que la zapata no recibe carga para dimensionar.',
  'footing.run.noServiceCases': 'Zapata {footing}: la capacidad portante es una verificación en servicio y este proyecto no tiene resultados por caso para sumar con factores unitarios. NO se aproximó dividiendo la reacción mayorada por un factor de carga supuesto.',
  'footing.run.noGravityCase': 'Zapata {footing}: ningún caso de carga gravitatoria (D, L, Lr, S, R) llega a este nudo, por lo que no pudo armarse una reacción de servicio.',
  'footing.run.serviceLateralExcluded': 'Zapata {footing}: la verificación de capacidad portante en servicio cubre sólo gravedad. Se excluyeron los casos {cases} porque sus factores de combinación en servicio no están modelados en este proyecto, por lo que la capacidad portante bajo ellos NO está verificada.',
  'footing.run.rotationNotResolved': 'La zapata {footing} está rotada {rotation}° en planta. Los momentos de reacción se informan en ejes globales y no se proyectan sobre los ejes rotados de la zapata, por lo que la excentricidad no puede asignarse correctamente.',
  'footing.run.noColumn': 'La zapata {footing} no tiene columna identificada, por lo que no pueden derivarse el perímetro de punzonado ni los pelos de anclaje. La capacidad portante y el corte en una dirección no la necesitan, pero una zapata con punzonado sin verificar no es una zapata verificada.',
  'footing.run.noColumnBars': 'Zapata {footing}: la columna no tiene barras longitudinales resueltas, por lo que no se generaron pelos ni estribos de arranque.',
  'footing.run.noEffectiveDepth': 'Zapata {footing}: el recubrimiento y el diámetro de barra no dejan altura útil.',
  // ── Resultados del dimensionamiento de la parrilla inferior ─────
  'footing.mat.upliftNotEvaluated': 'Dirección {axis}: la excentricidad de carga de {e} m sale del núcleo central ({limit} m), por lo que la base se despega parcialmente y la distribución lineal de presiones deja de ser válida. No se dimensiona una parrilla para un diagrama de presiones que el suelo no está entregando.',
  'footing.mat.geometryNotEvaluated': 'Dirección {axis}: no hay voladizo, ancho de reparto o presión de suelo con los cuales dimensionar la parrilla.',
  'footing.mat.needsCompressionSteel': 'Dirección {axis}: Mu = {Mu} kN·m supera lo que puede tomar una sección con armadura simple de {thickness} m de altura, por lo que el cálculo de resistencia recurre a armadura de compresión. Una zapata aislada es de armadura simple por construcción; la respuesta es aumentar la altura, no una parrilla superior tomando el momento del voladizo.',
  'footing.mat.depthBelowMinimum': 'Dirección {axis}: la altura útil a flexión es {d} m, menor que los {min} m que el artículo 13.3.1.2 exige para la armadura inferior. Hay que aumentar la altura total.',
  'footing.mat.noFeasibleLayout': 'Dirección {axis}: no existe disposición admisible con Ø{diameter} en la región {region} (de {width} m de ancho) — límite alcanzado: {reason}. El diámetro seleccionado NO se cambió y no se informa ninguna disposición como aceptable.',
  'footing.mat.regionBelowPolicyMinimum': 'Dirección {axis}: la región {region} provee {provided} cm², por debajo de los {policy} cm² que 0,0018·Ag pediría a esa faja por separado. Es una nota de conservadurismo de Stabileo, NO un requisito del CIRSOC: el artículo 7.6.1 impone su mínima a la armadura de la dirección y el 13.3.3.3 después reparte el total, y ninguno la vuelve a imponer región por región. El dimensionamiento sigue el reglamento.',
  'footing.mat.bandOutsideFooting': 'Dirección {axis}: el artículo 13.3.3.3 (b) dispone una faja central de {band} m sobre el eje de la columna, y con un corrimiento de {offset} m no entra en el ancho de {width} m. Recortar la faja sería inventar una regla que el artículo no establece, y repartir uniformemente sería eliminar la faja que exige.',
  'footing.run.columnDoesNotFit': 'Zapata {footing}: más de dos caras del perímetro crítico caen fuera de la zapata. La columna no entra en esta base.',
  'footing.assumption.serviceFromGravityCases': 'Zapata {footing}: reacción de servicio para capacidad portante sumada con factores unitarios sobre {cases}. Este proyecto no modela ninguna combinación de carga en servicio, por lo que la suma es una hipótesis y no una combinación declarada por el reglamento.',
  'footing.assumption.averageMatDepth': 'Zapata {footing}: altura útil tomada como {d} m, la altura PROMEDIO de la malla para una parrilla en dos direcciones de Ø{bar} mm. Las dos direcciones se ubican en realidad a alturas distintas.',
  'footing.assumption.flexuralDepths': 'La flexión se dimensiona con la altura útil propia de cada dirección: {dx} m para las barras Ø{bx} paralelas a B y {dy} m para las Ø{by} paralelas a L. El punzonamiento y el corte en una dirección conservan la altura promedio de dos capas, {punching} m. La diferencia es deliberada, no una discrepancia.',
  'footing.assumption.layerEnvelope': 'Las dos parrillas perpendiculares se superponen, por lo que cada dirección es la capa inferior o la superior, y ningún artículo decide cuál. Se conocen las dos alturas —X daría {lowx} m como inferior o {upx} m como superior; Y, {lowy} m o {upy} m— y AMBAS direcciones se dimensionan con su altura de capa superior, que es la envolvente conservadora. El artículo 24.3.2 usa cc = {cc} mm, el recubrimiento libre de la parrilla que quede más cerca de la cara traccionada, que es el mismo número en cualquiera de los dos casos. Se informa así porque NINGUNA de las dos disposiciones físicas resultó reglamentaria y por lo tanto no hay un orden que dimensionar.',
  'footing.assumption.layerOrderResolved': 'Orden físico de capas resuelto: {order} — la parrilla {lower} va en la capa inferior ({rationale}). Cada dirección se dimensiona con su altura útil REAL: dX = {dx} m, dY = {dy} m, con los ejes de barra a {ex} mm y {ey} mm sobre la cara inferior. Ya no se aplica la envolvente conservadora de PR18-A, que describía una barra colocada un diámetro más arriba que la real.',
  'footing.assumption.momentOrientationEnvelope': 'Los momentos mayorados ({mb} kN·m respecto de B, {ml} kN·m respecto de L) llegan como momentos de reacción en ejes globales, y acá no se resuelve su signo sobre un eje local de la zapata. Por eso cada uno se aplica en LAS DOS orientaciones y gobierna la sección crítica más desfavorable. Eso no puede subestimar la demanda, y puede dimensionar la zapata para un diagrama de presiones que el signo real no produciría.',
  'footing.assumption.truncatedPerimeter': 'Zapata {footing}: {sides} cara(s) del perímetro crítico llegan al borde de la zapata, por lo que el punzonado se verificó como caso {position}.',

  'detailing.footingRun.activeResultSet': 'Conjunto de resultados activo (ninguna combinación resuelta)',

  'footing.run.perimeterOppositeFaces': 'Zapata {footing}: dos caras OPUESTAS del perímetro crítico llegan al borde de la zapata. El art. 22.6.5.3 tabula α_s sólo para los casos interior, de borde y de esquina, y éste no es ninguno de ellos: aplicar el α_s de esquina a un perímetro de otra forma sería usar el coeficiente equivocado, por lo que no se verifica el punzonado.',


